<?php require_once __DIR__.'/includes/auth.php';$id=(int)($_GET['id']??0);$s=db()->prepare("SELECT u.id,u.name,u.city,u.state,u.area,b.*,c.name category FROM users u JOIN business_profiles b ON b.user_id=u.id LEFT JOIN categories c ON c.id=b.category_id WHERE u.id=? AND u.role='business' AND u.status='active'");$s->execute([$id]);$p=$s->fetch();if(!$p){http_response_code(404);include __DIR__.'/404.php';exit;}$sv=db()->prepare("SELECT ps.*,s.name FROM provider_services ps JOIN services s ON s.id=ps.service_id WHERE ps.provider_user_id=? AND ps.is_active=1");$sv->execute([$id]);$services=$sv->fetchAll();$rating=rating_summary($id);$rv=db()->prepare("SELECT r.*,u.name customer_name FROM reviews r JOIN users u ON u.id=r.customer_id WHERE r.target_user_id=? AND r.status='published' ORDER BY r.created_at DESC LIMIT 8");$rv->execute([$id]);$reviews=$rv->fetchAll();$viewer=current_user();$favorite=$viewer&&$viewer['role']==='customer'?is_favorite((int)$viewer['id'],$id):false;$pageTitle=e($p['business_name']?:$p['name']).' — LocalConnect';require __DIR__.'/includes/header.php';?><div class="container py-5"><div class="soft-card p-5 mb-4"><div class="d-flex flex-column flex-md-row gap-4"><img class="profile-hero" src="<?=e($p['logo']?base_url($p['logo']):base_url('assets/images/avatar-placeholder.svg'))?>" alt=""><div><h1 class="fw-bold"><?=e($p['business_name']?:$p['name'])?> <?php if($p['verification_status']==='verified'):?><span class="text-primary"><i class="fa fa-circle-check"></i></span><?php endif;?></h1><div class="text-primary fw-semibold"><?=e($p['category']?:'Local business')?></div><div class="text-muted"><i class="fa fa-location-dot"></i> <?=e(trim(($p['area']??'').' '.($p['city']??'').' '.($p['state']??'')))?></div><div class="text-warning mt-2"><i class="fa fa-star"></i> <?=number_format((float)$rating['avg_rating'],1)?> <span class="text-muted">(<?=$rating['total']?> reviews)</span></div></div></div></div><div class="row g-4"><div class="col-lg-8"><div class="soft-card p-4 mb-4"><h3>About</h3><p><?=nl2br(e($p['description']?:'Business profile details are being completed.'))?></p><p class="mb-0"><strong>Address:</strong> <?=e($p['address']?:'Not specified')?></p></div><div class="soft-card p-4"><h3>Services</h3><?php foreach($services as $x):?><div class="service-row my-3"><strong><?=e($x['title']?:$x['name'])?></strong><?php if($x['description']):?><p class="my-2"><?=e($x['description'])?></p><?php endif;?><span><?= $x['price_from']!==null?'Starting from ₹'.number_format((float)$x['price_from'],0):'Price on request'?></span></div><?php endforeach;?><?php if(!$services):?><p class="text-muted">No services listed yet.</p><?php endif;?></div></div><div class="col-lg-4"><div class="soft-card p-4"><h4>Business details</h4><p><strong>Phone:</strong> <?=e($p['phone']?:'Not listed')?></p><p><strong>Hours:</strong> <?=e(($p['opening_time']&&$p['closing_time'])?$p['opening_time'].' – '.$p['closing_time']:'Contact business')?></p><p><strong>Price range:</strong> <?= $p['price_min']!==null?'₹'.number_format((float)$p['price_min'],0).($p['price_max']?' – ₹'.number_format((float)$p['price_max'],0):'+'):'Price on request'?></p></div></div></div></div><div class="container pb-4"><div class="soft-card p-4 d-flex justify-content-between align-items-center flex-wrap gap-3"><div><strong>Need this service?</strong><div class="text-muted small">Send a request with your preferred date, location and budget.</div></div><?php if($viewer&&$viewer['role']==='customer'):?><button class="btn <?= $favorite?'btn-danger':'btn-outline-danger' ?> js-favorite" data-target="<?=$id?>"><i class="<?= $favorite?'fa-solid':'fa-regular' ?> fa-heart me-1"></i> <?= $favorite?'Saved':'Save' ?></button><?php endif;?> <a class="btn btn-primary" href="<?=e(base_url('request-service.php?type=business&provider='.$id))?>">Request Service</a></div></div><div class="container pb-4"><div class="soft-card p-4"><h3 class="h5">Customer Reviews</h3><?php if(!$reviews):?><p class="text-muted mb-0">No reviews yet.</p><?php endif;?><?php foreach($reviews as $x):?><div class="border-top py-3"><strong><?=e($x['customer_name'])?></strong><span class="text-warning ms-2"><?=str_repeat('★',(int)$x['rating'])?></span><div class="small text-muted"><?=e(date('d M Y',strtotime($x['created_at'])))?></div><?php if($x['comment']):?><p class="mb-0 mt-1"><?=e($x['comment'])?></p><?php endif;?></div><?php endforeach;?></div></div><?php require __DIR__.'/includes/footer.php';?>
